'use client';

import { Card, CardContent } from '@/components/ui/card';
import { useTranslations } from 'next-intl';
import { Users, BookOpen, Award, Star } from 'lucide-react';

export default function StatsSection() {
  const t = useTranslations('HomePage');
  const stats = [
    {
      icon: Users,
      value: '১৭ মিলিয়ন+',
      label: 'শিক্ষার্থী',
      description: 'সারাদেশে আমাদের শিক্ষার্থী',
    },
    {
      icon: BookOpen,
      value: '১০০০+',
      label: 'কোর্স',
      description: 'বিভিন্ন বিষয়ে কোর্স',
    },
    {
      icon: Award,
      value: '৫০০+',
      label: 'দক্ষ শিক্ষক',
      description: 'অভিজ্ঞ ও যোগ্য শিক্ষক',
    },
    {
      icon: Star,
      value: '৪.৮/৫',
      label: 'রেটিং',
      description: 'শিক্ষার্থীদের গড় রেটিং',
    },
  ];

  return (
    <section className="py-16 bg-gradient-to-r from-primary/5 via-background to-secondary/5">
      <div className="container mx-auto px-4">
        {/* Section Header */}
        <div className="text-center mb-12">
          <h2 className="text-3xl md:text-4xl font-bold text-foreground mb-4">
            {t('stats.title')}
          </h2>
          <p className="text-lg text-muted-foreground max-w-2xl mx-auto">
            {t('stats.subtitle')}
          </p>
        </div>

        {/* Stats Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {stats.map((stat, index) => {
            const IconComponent = stat.icon;
            return (
              <Card
                key={index}
                className="text-center hover:shadow-lg transition-shadow duration-300"
              >
                <CardContent className="p-6">
                  {/* Icon */}
                  <div className="w-16 h-16 mx-auto mb-4 bg-primary/10 rounded-full flex items-center justify-center">
                    <IconComponent className="w-8 h-8 text-primary" />
                  </div>

                  {/* Value */}
                  <div className="text-3xl md:text-4xl font-bold text-foreground mb-2">
                    {stat.value}
                  </div>

                  {/* Label */}
                  <div className="text-lg font-semibold text-foreground mb-1">
                    {stat.label}
                  </div>

                  {/* Description */}
                  <div className="text-sm text-muted-foreground">
                    {stat.description}
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>

        {/* Bottom CTA */}
        <div className="text-center mt-12">
          <div className="bg-primary/10 rounded-2xl p-8 max-w-4xl mx-auto">
            <h3 className="text-2xl md:text-3xl font-bold text-foreground mb-4">
              {t('stats.cta.title')}
            </h3>
            <p className="text-lg text-muted-foreground mb-6">
              {t('stats.cta.subtitle')}
            </p>
            <div className="flex flex-col sm:flex-row gap-4 justify-center">
              <button className="bg-primary text-primary-foreground px-8 py-3 rounded-full font-semibold hover:bg-primary/90 transition-colors">
                {t('stats.cta.startNow')}
              </button>
              <button className="border-2 border-primary text-primary px-8 py-3 rounded-full font-semibold hover:bg-primary hover:text-primary-foreground transition-colors">
                {t('stats.cta.learnMore')}
              </button>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
